package com.ianblk.zianmanager;
import com.ianblk.zianmanager.core.*;
import java.time.Instant;
import java.util.*;
import net.minecraft.server.level.ServerPlayer;
public final class DailyTimeSmoke {
 public static void verify(ManagerRuntime runtime,ServerPlayer first)throws Exception{var original=runtime.dungeonTime();var server=first.getServer();var base=server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data/zianmanager/smoke-time-"+UUID.randomUUID());var time=new DungeonTimeRuntime(server,base);var runtimeField=ManagerRuntime.class.getDeclaredField("dungeonTime");runtimeField.setAccessible(true);runtimeField.set(runtime,time);var previous=time.settings();var file=base.resolve("dungeon-time-usage.json");var settings=new DailyDungeonTime.Settings(true,List.of("minecraft:overworld"),"America/Guayaquil",1,1,2,2,"zianmanager.dungeon.vip","zianmanager.dungeon.bypass","execute in minecraft:the_nether run tp {player} 2048 201 2048");time.configure(settings);var field=DungeonTimeRuntime.class.getDeclaredField("usage");field.setAccessible(true);var usage=(DailyDungeonTime)field.get(time);var day=settings.day(Instant.now());usage.charge(Map.of(first.getUUID(),60L),day);server.getPlayerList().op(first.getGameProfile());try{time.tick();if(!time.unlimited(first) || !first.serverLevel().dimension().equals(net.minecraft.world.level.Level.OVERWORLD))throw new IllegalStateException("OP was charged or ejected");server.getCommands().getDispatcher().execute("zianmanager bonustime player "+first.getGameProfile().getName()+" 30",first.createCommandSourceStack());if(time.remaining(first)!=1800)throw new IllegalStateException("Personal bonus command did not add 30 minutes");server.getCommands().getDispatcher().execute("zianmanager bonustime all 30",first.createCommandSourceStack());if(time.remaining(first)!=3600)throw new IllegalStateException("Global bonus command did not add 30 minutes");}finally{server.getPlayerList().deop(first.getGameProfile());}usage.charge(Map.of(first.getUUID(),3600L),day);if(time.remaining(first)!=0)throw new IllegalStateException("Daily exhaustion not recognized");time.tick();if(!first.serverLevel().dimension().equals(net.minecraft.world.level.Level.NETHER))throw new IllegalStateException("Exhausted player not sent using console exit command");var overworld=server.overworld();var spawn=overworld.getSharedSpawnPos();first.teleportTo(overworld,spawn.getX(),spawn.getY()+2,spawn.getZ(),Set.of(),0,0);time.tick();if(!first.serverLevel().dimension().equals(net.minecraft.world.level.Level.NETHER))throw new IllegalStateException("Reentry did not enforce depleted daily time");time.configure(previous);runtimeField.set(runtime,original);first.teleportTo(overworld,spawn.getX(),spawn.getY()+2,spawn.getZ(),Set.of(),0,0);if(new DailyDungeonTime(file).used(first.getUUID(),day)!=3660)throw new IllegalStateException("Daily time not persisted");ZianManager.LOGGER.info("Zian Manager daily time smoke passed: OP bypass, personal/global bonuses, exhaustion console teleport, rejected reentry and persisted usage");}
}
